/users/gusfcarvalho", "user_view_type": "public"}}, {"type": "reporter", "user": {"avatar_url": "https://avatars.githubusercontent.com/u/254865007?v=4", "events_url": "https://api.github.com/users/evrardj-roche/events{/privacy}", "followers_url": "https://api.github.com/users/evrardj-roche/followers", "following_url": "https://api.github.com/users/evrardj-roche/following{/other_user}", "gists_url": "https://api.github.com/users/evrardj-roche/gists{/gist_id}", "gravatar_id": "", "html_url": "https://github.com/evrardj-roche", "id": 254865007, "login": "evrardj-roche", "node_id": "U_kgDODzDubw", "organizations_url": "https://api.github.com/users/evrardj-roche/orgs", "received_events_url": "https://api.github.com/users/evrardj-roche/received_events", "repos_url": "https://api.github.com/users/evrardj-roche/repos", "site_admin": false, "starred_url": "https://api.github.com/users/evrardj-roche/starred{/owner}{/repo}", "subscriptions_url": "https://api.github.com/users/evrardj-roche/subscriptions", "type": "User", "url": "https://api.github.com/users/evrardj-roche", "user_view_type": "public"}}], "cve_id": "CVE-2026-26287", "cvss": {"score": 7.1, "vector_string": "CVSS:3.1/AV:N/AC:L/PR:L/UI:N/S:U/C:H/I:L/A:N"}, "cvss_severities": {"cvss_v3": {"score": 7.1, "vector_string": "CVSS:3.1/AV:N/AC:L/PR:L/UI:N/S:U/C:H/I:L/A:N"}, "cvss_v4": {"score": 0.0, "vector_string": null}}, "cwes": [{"cwe_id": "CWE-696", "name": "Incorrect Behavior Order"}], "description": "## Summary
A bug in the `webhook` generator initialization order incorrectly cleared the label-enforcement flag (`EnforceLabels`) after it was set, resulting in the provider-side check for `external-secrets.io/type=webhook` being skipped (and the operation to succeed while it should have failed with `secret does not contain needed label 'external-secrets.io/type: webhook'. Update secret label to use it with webhook`.

## Impact
A user with the permission to create webhook generator can set the webhook generator to a victim' secret (which was not previously labelled for webhook's use), and exfiltrate it to a malicious URL.

## Mitigations
Until you upgrade, you can reduce risk by:
- disabling webhook generators if not needed (or denying `generators.external-secrets.io/v1alpha1` `Webhook` via an admission policy);
- restricting RBAC: limit who can create generators of kind `Webhook`;
- enforcing an admission policy (OPA Gatekeeper / Kyverno) requiring referenced secrets to be labeled `external-secrets.io/type=webhook`;
- restricting egress from external-secrets controller pods to an allowlist (kubernetes `NetworkPolicy` / service mesh egress policy).

